t.script:
(function(){
  var f = document.getElementById('dmn_q_form');
  var box = document.getElementById('dmn_q_alert');
  var btn = document.getElementById('dmn_q_submit');
  var result = document.getElementById('dmn_q_result');

  function readFile(input){
    return new Promise(function(resolve){
      var file = input.files && input.files[0];
      if(!file){ resolve(null); return; }
      var r = new FileReader();
      r.onload = function(){ resolve(r.result); };
      r.onerror = function(){ resolve(null); };
      r.readAsDataURL(file);
    });
  }

  f.addEventListener('submit', function(e){
    e.preventDefault();
    box.innerHTML = '';
    btn.disabled = true; btn.textContent = 'Creando...';
    readFile(f.foto).then(function(foto){
      var p = {
        joya: f.joya.value, metal: f.metal.value, medidas: f.medidas.value,
        pieza: f.pieza.value, plastico: f.plastico.value, foto: foto
      };
      return fetch('/dmn/alta/crear', {method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({jsonrpc:'2.0', method:'call', params:p, id:1})});
    })
    .then(function(r){return r.json();})
    .then(function(d){
      btn.disabled = false; btn.textContent = 'Crear pieza';
      var res = d.result || {};
      if(res.ok){
        f.style.display = 'none';
        var qr = document.getElementById('dmn_q_qr');
        qr.src = '/report/barcode?barcode_type=QR&value=' + encodeURIComponent(res.visor_url) + '&width=260&height=260';
        var link = document.getElementById('dmn_q_link');
        link.href = res.visor_url;
        result.style.display = 'block';
        result.scrollIntoView({behavior:'smooth'});
      } else {
        box.innerHTML = '<div class="alert alert-danger">' + (res.error || 'No se pudo crear la pieza.') + '</div>';
      }
    })
    .catch(function(){
      btn.disabled = false; btn.textContent = 'Crear pieza';
      box.innerHTML = '<div class="alert alert-danger">Error de conexión.</div>';
    });
  });

  document.getElementById('dmn_q_again').addEventListener('click', function(){
    f.reset(); f.style.display = 'block'; result.style.display = 'none'; box.innerHTML = '';
    window.scrollTo({top:0, behavior:'smooth'});
  });
})();

(function(){
  var f = document.getElementById('dmn_reg_form');
  var box = document.getElementById('dmn_reg_alert');
  f.addEventListener('submit', function(e){
    e.preventDefault();
    var p = {token: f.token.value, name: f.name.value, email: f.email.value, phone: f.phone.value};
    fetch('/dmn/claim', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:p, id:1})})
    .then(function(r){return r.json();})
    .then(function(d){
      var res = d.result || {};
      if(res.ok){
        var g = res.warranty_until ? (' Garantia hasta ' + res.warranty_until + '.') : '';
        box.innerHTML = '<div class="alert alert-success">Listo, ' + res.partner + '. Tu joya quedo registrada a tu nombre.' + g + '</div>';
        f.style.display = 'none';
        setTimeout(function(){ window.location.href='/visor'; }, 2500);
      } else {
        box.innerHTML = '<div class="alert alert-danger">' + (res.error || 'No se pudo registrar.') + '</div>';
      }
    })
    .catch(function(){ box.innerHTML = '<div class="alert alert-danger">Error de conexion.</div>'; });
  });
})();

xpath.script:
(function(){
  fetch('/dmn/dedication', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{}, id:1})})
  .then(function(r){return r.json();})
  .then(function(d){
    var res = d.result || {};
    if(!res.visible){return;}
    document.getElementById('dmn_ded_text').textContent = res.text || '';
    document.getElementById('dmn_ded_from').textContent = res.from ? ('- ' + res.from) : '';
    if(res.image){ var im = document.getElementById('dmn_ded_img'); im.src = res.image; im.style.display='block'; }
    document.getElementById('dmn_dedication_block').style.display = 'flex';
  }).catch(function(){});
})();
